def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(r for r, row in enumerate(grid) if all(v == 2 for v in row))
    out = [[0] * w for _ in range(h)]
    out[wall] = list(grid[wall])
    for r in range(h):
        if r == wall:
            continue
        for c, value in enumerate(grid[r]):
            if value != 4:
                continue
            if r < wall:
                nr = r + 1
                if nr < wall:
                    out[nr][c] = 4
                    if nr == wall - 1:
                        for step in range(1, max(h, w) + 1):
                            rr = nr - step
                            for nc in (c - step, c + step):
                                if 0 <= rr < h and 0 <= nc < w:
                                    out[rr][nc] = 4
            elif r == wall + 1:
                out[r][c] = 4
            else:
                out[r + 1][c] = 4
    return out

